/*
Theme Name: Careful Shopper — Twenty Twenty-Five Child
Template: twentytwentyfive
Author: Careful Shopper demo
Description: MHTML-inspired styling aligned to the Careful Shopper Style Sheet.
Version: 1.4.2
Text Domain: careful-shopper
*/

/* Core palette and sizing: rem-based to support zoom and text scaling. */
:root{
  --cs-green:#075C37;
  --cs-deep:#06472D;
  --cs-blue:#075C37;
  --cs-gold:#B78B2E;
  --cs-ink:#14251C;
  --cs-muted:#24352B;
  --cs-paper:#FBFAF6;
  --cs-line:#D9E2D8;
  --cs-mint:#EAF3EE;
  --cs-beige:#F2EEE4;
  --cs-disclosure:#FFF8DF;
  --cs-disclosure-border:#D7B65A;
}
*{box-sizing:border-box;min-width:0}
html,body,.wp-site-blocks{max-width:100%;}
img,iframe,video,svg{max-width:100%;}
html{font-size:100%}
body{
  margin:0;
  background:var(--cs-paper);
  color:var(--cs-ink);
  font-family:Verdana,Geneva,Arial,sans-serif;
  font-size:1rem;
  line-height:1.6;
}
a{
  color:var(--cs-blue);
  font-weight:700;
  text-decoration:underline;
  text-underline-offset:.16em;
  text-decoration-thickness:.0625rem;
  cursor:pointer;
}
a:hover{color:var(--cs-deep);text-decoration-thickness:.125rem}
a:focus-visible,button:focus-visible{
  outline:.2rem solid var(--cs-gold);
  outline-offset:.2rem;
}
button{cursor:pointer;font-family:inherit}
main,.wp-site-blocks main{
  width:min(60rem,calc(100% - 2rem));
  max-width:100%;
  min-width:0;
  margin:2rem auto 3rem;
}
.zone{
  position:relative;
  overflow:hidden;
  margin:0 0 1.5rem;
  padding:2rem;
  border:.0625rem solid var(--cs-line);
  border-radius:1.75rem;
  background:#FFFFFF;
  box-shadow:none;
}

/* Header: compact identity, single-line desktop navigation, accessible phone menu. */
.site-header{
  padding:1rem;
  background:#FFFFFF;
  border-bottom:.125rem solid var(--cs-line);
}
.header-inner{
  width:min(70rem,100%);
  max-width:100%;
  min-width:0;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:1rem;
}
.brand{
  display:flex;
  flex:0 0 auto;
  align-items:center;
  min-width:0;
  color:var(--cs-green);
  text-decoration:none;
}
.brand-mark{
  display:grid;
  place-items:center;
  flex:0 0 3rem;
  width:3rem;
  height:3rem;
  border:.0625rem solid var(--cs-green);
  border-radius:.75rem;
  background:var(--cs-mint);
  color:var(--cs-green);
  font-size:1rem;
  font-weight:700;
  text-decoration:none;
}
.brand-copy{display:flex;flex-direction:column;line-height:1.25;min-width:0}
.brand-name{color:#075C37;font-size:1.375rem;font-weight:800;letter-spacing:-.03125rem;text-decoration:none}
.brand-dot{color:#B78B2E}
.tagline{margin-top:.25rem;color:#66766B;font-size:.6875rem;font-weight:400;letter-spacing:.125rem;text-transform:uppercase}
.desktop-nav{
  display:flex;
  flex:0 0 auto;
  flex-direction:row;
  flex-wrap:nowrap;
  align-items:center;
  justify-content:flex-end;
  gap:1.25rem;
  margin-left:auto;
  white-space:nowrap;
}
.desktop-nav a,.mobile-nav a{
  color:#075C37;
  font-size:1rem;
  font-weight:700;
  text-decoration:none;
  cursor:pointer;
}
.desktop-nav a:hover,.mobile-nav a:hover{text-decoration:underline;text-underline-offset:.15em}
.nav-unavailable{
  color:var(--cs-blue);
  font-size:1rem;
  font-weight:700;
  text-decoration:none;
  cursor:default;
}
.menu-button{
  display:none;
  min-height:3rem;
  padding:.75rem 1rem;
  border:0;
  border-radius:.5rem;
  background:#663300;
  color:#FFFFFF;
  font-size:1rem;
  font-weight:700;
}
.menu-button{cursor:pointer}
.menu-button:hover{background:#663300;color:#FFFFFF}
.mobile-nav{
  display:none;
  max-width:100%;
  min-width:0;
  width:min(70rem,calc(100% - 2rem));
  margin:.75rem auto 0;
  padding:1rem;
  border:.0625rem solid var(--cs-line);
  border-radius:.75rem;
  background:#FFFFFF;
}
.mobile-nav.open{display:flex;flex-direction:column;align-items:stretch;gap:.5rem}
.mobile-nav a{
  display:flex;
  align-items:center;
  min-height:3rem;
  padding:.75rem 0;
  border-bottom:.0625rem solid var(--cs-line);
  cursor:pointer;
}
.mobile-nav a:last-child{border-bottom:0}

/* Hero keeps the forest-green editorial identity while following the specified type scale. */
.hero{
  padding:2rem;
  border:0;
  border-radius:1.75rem;
  background:var(--cs-green);
  color:#FFFFFF;
  box-shadow:none;
}
.hero:after{
  content:"";
  position:absolute;
  right:-6rem;
  top:-8rem;
  width:22rem;
  height:22rem;
  border:.0625rem solid #FFFFFF;
  border-radius:50%;
  box-shadow:none;
  pointer-events:none;
}
.hero>*{position:relative;z-index:1;max-width:52rem}
.hero h1{margin:.5rem 0 1rem;color:#FFFFFF;font-size:1.4rem;line-height:1.35;font-weight:700}
.hero a,.hero .breadcrumb,.hero .byline,.hero .short-answer{color:#FFFFFF}
.breadcrumb{margin:0 0 .75rem;font-size:1rem}
.byline{margin-bottom:.875rem}
.short-answer{
  padding:1rem 1.125rem;
  border-left:.375rem solid var(--cs-gold);
  border-radius:0 .875rem .875rem 0;
  background:rgba(255,255,255,.1);
}

/* Disclosure is deliberately prominent and must remain adjacent to product links. */
.disclosure{
  padding:1.25rem;
  border:.0625rem solid var(--cs-disclosure-border);
  border-left:.375rem solid var(--cs-gold);
  border-radius:.875rem;
  background:var(--cs-disclosure);
  color:#463719;
  font-size:1.333rem;
  font-weight:400;
  font-style:normal;
  line-height:1.5;
}

/* Education and photograph. */
.education{background:#FFFFFF}
h2{
  margin:0 0 1rem;
  color:var(--cs-green);
  font-size:1.2rem;
  line-height:1.35;
  font-weight:700;
}
h3{margin:.75rem 0 .5rem;color:var(--cs-green);font-size:1rem;line-height:1.4;font-weight:700}
p{margin:0 0 1rem}
p:last-child{margin-bottom:0}
.bite-photo-wrap{
  float:left;
  width:40%;
  max-width:26ch;
  margin:0 1.25rem .75rem 0;
}
.bite-photo{
  display:block;
  width:100%;
  height:auto;
  aspect-ratio:16/9;
  object-fit:cover;
  border-radius:1.5rem;
}
.photo-credit{
  display:block;
  width:100%;
  margin:.25rem 0 0;
  color:#000000;
  text-align:center;
  font-size:.85rem;
  font-weight:400;
}
.education-second{clear:both;padding-top:.5rem}

/* Three-layer strip: source card dimensions plus the MHTML layer markers/accent tops. */
.layer-zone,.pairing-zone{background:var(--cs-mint);border-color:var(--cs-line)}
.layer-grid{min-width:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}
.layer-card{
  padding:1.375rem;
  border:.0625rem solid var(--cs-line);
  border-top:.3125rem solid var(--cs-green);
  border-radius:1.5rem;
  background:#FFFFFF;
}
.layer-card:nth-child(2){border-top-color:var(--cs-gold)}
.layer-card:nth-child(3){border-top-color:#6B8F79}
.layer-number{
  margin:0 0 .5rem;
  color:var(--cs-gold);
  font-size:.75rem;
  font-weight:700;
  letter-spacing:.0625rem;
}
.layer-card h3{margin:.5rem 0;color:var(--cs-green);font-size:1.25rem;line-height:1.35;font-weight:700;text-transform:uppercase}
.layer-card p{margin:0;font-size:1rem}
.layer-close{margin:1rem 0 0;padding:1rem;border:.0625rem solid var(--cs-line);border-radius:.75rem;background:#FFFFFF}

/* Comparison table: white header and black rules; only this wrapper may scroll sideways. */
.comparison{background:#FFFFFF}
.table-wrap{
  width:100%;
  min-width:0;
  max-width:100%;
  overflow-x:auto;
  border:.0625rem solid var(--cs-line);
  border-radius:1.125rem;
  background:#FFFFFF;
}
table{
  width:100%;
  min-width:42rem;
  border-collapse:collapse;
  color:#000000;
  font-size:1rem;
  line-height:1.5;
}
th,td{
  padding:.875rem;
  border-bottom:.0625rem solid #E5EAE4;
  text-align:left;
  vertical-align:top;
}
th{background:var(--cs-green);color:#FFFFFF;font-weight:700}
tbody tr:nth-child(even){background:var(--cs-paper)}

/* Barrier and pairing product cards. */
.barrier-zone{background:var(--cs-beige);border-color:var(--cs-line)}
.card-zone-intro{margin:0 0 1rem}
.product-grid{
  width:100%;
  max-width:100%;
  min-width:0;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,14rem));
  justify-content:center;
  gap:1rem;
}
.product-card{
  min-width:0;
  display:flex;
  flex-direction:column;
  align-items:stretch;
  width:100%;
  max-width:14rem;
  margin-inline:auto;
  padding:1.375rem;
  border:.0625rem solid var(--cs-line);
  border-radius:1.5rem;
  background:#FFFFFF;
}
.product-window{
  display:flex;
  width:100%;
  min-height:0;
  aspect-ratio:16/10;
  align-items:center;
  justify-content:center;
  border:0;
  border-radius:1rem;
  background:var(--cs-mint);
  color:var(--cs-green);
  text-align:center;
  font-size:1rem;
  font-weight:700;
  text-decoration:underline;
}
.product-window:hover{color:var(--cs-blue)}
.product-card h3{margin:1rem 0 .5rem;color:var(--cs-green);font-size:1.25rem;font-weight:700}
.caption-line{margin:0 0 .75rem;color:#000000;font-size:1rem;font-weight:400}
.caption-line strong{color:#000000;font-weight:700}
.product-cta{
  display:flex;
  align-items:center;
  justify-content:center;
  min-height:3rem;
  margin-top:auto;
  padding:.75rem 1rem;
  border:.0625rem solid #663300;
  border-radius:.5rem;
  background:#663300;
  color:#FFFFFF;
  text-align:center;
  text-decoration:underline;
  text-underline-offset:.12em;
  font-size:1rem;
  font-weight:700;
}
.product-cta:hover{background:#663300;color:#FFFFFF;text-decoration:underline}
.card-spacer{height:.75rem;flex:1 0 .75rem}
.pairing-zone .product-card{background:#FFFFFF}

/* Footer links remain white, bold and underlined like every other text link. */
.footer-zone{background:var(--cs-green);color:#FFFFFF;border:0;border-radius:1.75rem;padding:2rem}
.footer-zone h2,.footer-zone h3{color:#FFFFFF}
.footer-zone a,.footer-nav a{color:#FFFFFF;font-weight:700;text-decoration:underline}
.footer-nav{display:flex;flex-direction:row;flex-wrap:wrap;gap:1.5rem;margin:1.5rem 0}
.footer-nav a{font-size:1rem;cursor:pointer}
.footer-note{margin:1rem 0 0;padding-top:1rem;border-top:.0625rem solid #FFFFFF;color:#FFFFFF;font-size:1rem}
.copyright{margin:1rem 0 0;color:#FFFFFF;font-size:1rem}

/* Static page: no transitions, carousels, sliding elements or smooth-scroll animation. */
@media(max-width:55rem){
  .desktop-nav{display:none}
  .menu-button{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto}
  .header-inner{gap:1rem}
  .product-grid{grid-template-columns:repeat(2,minmax(0,14rem))}
}
@media(max-width:40rem){
  main,.wp-site-blocks main{width:calc(100% - 1rem);margin:1rem auto 2rem}
  .zone{padding:1.25rem;margin-bottom:1rem}
  .hero{padding:1.5rem}
  .hero:after{width:14rem;height:14rem;right:-6rem;top:-5rem}
  .mobile-nav{width:calc(100% - 1rem)}
  .layer-grid{grid-template-columns:minmax(0,1fr)}
  .product-grid{grid-template-columns:minmax(0,1fr)}
  .product-card{width:100%;max-width:14rem}
  .bite-photo-wrap{float:none;width:100%;max-width:none;margin:0 0 .75rem}
  .bite-photo{width:100%;aspect-ratio:16/9}
  .photo-credit{width:100%;margin:0 0 1rem}
  .education-second{clear:both}
  .footer-nav{flex-direction:row;flex-wrap:wrap;gap:1rem}
}
@media(prefers-reduced-motion:reduce){
  *{scroll-behavior:auto!important;animation:none!important;transition:none!important}
}

